(()=>{'use strict';
const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:2}).format(n||0),safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),key='complemento_pos_sales_v1';
let catalog=[],items=[],sales=[];try{sales=JSON.parse(localStorage.getItem(key)||'[]')}catch{}
const root=$('posPanel');if(!root)return;
root.innerHTML=`<div class="pos-shell"><div class="pos-head"><h2>🛒 Punto de Venta</h2><button id="posClose" type="button">Cerrar</button></div><p class="pos-note">Buscá por nombre o escaneá un código con un lector USB/Bluetooth. Las ventas se guardan en el panel y se sincronizan entre dispositivos. No se descuenta stock.</p><label>Buscar o escanear código de barras<input id="posSearch" autocomplete="off" placeholder="Nombre, código o código de barras"></label><div id="posResults" class="pos-results"></div><div style="overflow-x:auto"><table class="pos-table"><thead><tr><th>Producto</th><th>Cant.</th><th>Precio unit.</th><th>Subtotal</th><th></th></tr></thead><tbody id="posItems"></tbody></table></div><div class="pos-total">Total <strong id="posTotal">$0</strong></div><div class="pos-fields"><label>Cliente (opcional)<input id="posCustomer" placeholder="Nombre del cliente"></label><label>Dirección (opcional)<input id="posAddress" placeholder="Domicilio del cliente"></label><label>CUIT / CUIL / DNI (opcional)<input id="posCuit" placeholder="Número de documento"></label><label>Teléfono (opcional)<input id="posPhone" placeholder="Teléfono"></label><label>Forma de pago<select id="posPayment"><option>Efectivo</option><option>Transferencia</option><option>Débito</option><option>Crédito</option><option>Otro</option></select></label><label>Observaciones<input id="posNotes" placeholder="Notas del presupuesto o venta"></label></div><div class="pos-actions"><button id="posQuote" type="button">📄 Generar presupuesto / PDF</button><button id="posWhatsApp" type="button" style="background:#218b58">💬 Enviar por WhatsApp</button><button id="posSale" type="button" style="background:#237a57">✓ Registrar venta</button><button id="posClear" type="button" style="background:#64748b">Vaciar venta</button></div><p id="posStatus" role="status"></p><div class="pos-head"><h3>Historial de ventas (guardadas en el panel)</h3><button id="posExport" type="button">Descargar CSV</button></div><div id="posHistory"></div></div>`;
const css=document.createElement('style');css.textContent=`#posPanel{margin:14px 0;padding:16px;background:white;border:1px solid #ddd;border-radius:16px}.pos-shell{display:grid;gap:13px}.pos-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.pos-head h2,.pos-head h3{margin:0}.pos-note{color:#53616b;margin:0}.pos-results{max-height:220px;overflow:auto;display:grid;gap:5px}.pos-results button{background:#f3f5f8;color:#18242a;text-align:left;border:1px solid #dce1e4;display:flex;justify-content:space-between;gap:8px}.pos-table{width:100%;border-collapse:collapse;min-width:540px}.pos-table td,.pos-table th{padding:8px 5px;border-bottom:1px solid #e6e9ec;text-align:left}.pos-table input{width:85px}.pos-total{display:flex;justify-content:space-between;align-items:center;font-size:22px;font-weight:700;background:#f6eef3;padding:15px;border-radius:10px}.pos-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.pos-fields label{font-size:13px;color:#455}.pos-fields input,.pos-fields select{display:block;margin-top:5px}.pos-actions{display:flex;gap:9px;flex-wrap:wrap}.pos-actions button{flex:1 1 170px;padding:13px}.pos-history-row{padding:10px;border-bottom:1px solid #e4e4e4}`;document.head.append(css);
const total=()=>items.reduce((a,x)=>a+x.qty*x.price,0);
function render(){const query=$('posSearch').value.trim().toLocaleLowerCase('es');const normalized=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const matches=query?catalog.filter(p=>normalized(p.name+' '+p.sku+' '+(p.description||'')).includes(normalized(query))).slice(0,15):[];$('posResults').innerHTML=matches.map(p=>`<button type="button" data-pos-sku="${safe(p.sku)}"><span>${safe(p.name)} <small>(${safe(p.sku)})</small></span><b>${money(Number(p.price))}</b></button>`).join('');$('posItems').innerHTML=items.length?items.map((x,i)=>`<tr><td>${safe(x.name)}<div style="font-size:11px;color:#667">${safe(x.sku)}</div></td><td><input aria-label="Cantidad" type="number" min="1" max="9999" data-pos-qty="${i}" value="${x.qty}"></td><td><input aria-label="Precio" type="number" min="0" step="0.01" data-pos-price="${i}" value="${x.price}"></td><td>${money(x.qty*x.price)}</td><td><button type="button" data-pos-remove="${i}" aria-label="Quitar">✕</button></td></tr>`).join(''):'<tr><td colspan="5">Todavía no agregaste productos.</td></tr>';$('posTotal').textContent=money(total());}
function add(p){let x=items.find(x=>x.sku===String(p.sku));if(x)x.qty++;else items.push({sku:String(p.sku),name:p.name,qty:1,price:Number(p.price)||0});$('posSearch').value='';render();$('posSearch').focus()}
$('posSearch').addEventListener('input',render);$('posSearch').addEventListener('keydown',e=>{if(e.key!=='Enter')return;e.preventDefault();const q=e.target.value.trim();const exact=catalog.find(p=>String(p.sku).toLowerCase()===q.toLowerCase());const normalized=q.toLowerCase();const matches=catalog.filter(p=>(p.name+' '+p.sku).toLowerCase().includes(normalized));if(exact||matches.length===1)add(exact||matches[0]);else $('posStatus').textContent='Seleccioná el producto de la lista.'});
$('posResults').addEventListener('click',e=>{const b=e.target.closest('[data-pos-sku]');if(!b)return;const p=catalog.find(p=>String(p.sku)===b.dataset.posSku);if(p)add(p)});
$('posItems').addEventListener('change',e=>{const q=e.target.dataset.posQty,p=e.target.dataset.posPrice;if(q!==undefined)items[+q].qty=Math.max(1,Math.min(9999,Math.round(Number(e.target.value)||1)));if(p!==undefined)items[+p].price=Math.max(0,Number(e.target.value)||0);render()});$('posItems').addEventListener('click',e=>{const b=e.target.closest('[data-pos-remove]');if(b){items.splice(+b.dataset.posRemove,1);render()}});
function snapshot(){return{date:new Date().toISOString(),customer:$('posCustomer').value.trim(),address:$('posAddress').value.trim(),cuit:$('posCuit').value.trim(),phone:$('posPhone').value.trim(),payment:$('posPayment').value,notes:$('posNotes').value.trim(),items:items.map(x=>({...x})),total:total()}}
function printQuote(data,type='Comprobante de venta',popup=null){const w=popup||window.open('','_blank');if(!w){$('posStatus').textContent='Permití las ventanas emergentes para imprimir o guardar PDF.';return}const date=new Date(data.date||data.created_at).toLocaleString('es-AR');w.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${safe(type)} · Complemento</title><style>@page{size:A4 portrait;margin:0}*{box-sizing:border-box}html,body{width:210mm;min-height:297mm;margin:0;padding:0;color:#000;background:#fff;font:12px Arial,sans-serif}.sheet{width:210mm;height:297mm;padding:13mm 14mm;display:flex;flex-direction:column;overflow:hidden}.brand{display:flex;justify-content:space-between;align-items:flex-start;border:2px solid #000;padding:11px 12px}.logo{font-size:26px;font-weight:800}.tag{border:2px solid #000;padding:9px;font-weight:800;font-size:16px;text-align:center}.info{display:grid;grid-template-columns:1fr 1fr;border:2px solid #000;border-top:0}.info>div{padding:11px;border-right:1px solid #000;min-height:100px}.info>div:last-child{border-right:0}h3{font-size:11px;text-transform:uppercase;margin:0 0 9px}p{margin:5px 0}.detail{flex:1;min-height:0;border:2px solid #000;border-top:0;display:flex;flex-direction:column}table{border-collapse:collapse;width:100%;table-layout:fixed}th{border-bottom:2px solid #000}td,th{padding:8px 6px;text-align:left;overflow-wrap:anywhere}th:nth-child(1){width:51%}th:nth-child(2){width:12%}th:nth-child(3){width:18%}th:nth-child(4){width:19%}td:last-child,th:last-child{text-align:right}tr{break-inside:avoid}.bottom{margin-top:auto;border-top:2px solid #000;padding:10px 12px}.total{display:flex;justify-content:space-between;align-items:center;border:2px solid #000;padding:12px;font-size:22px;font-weight:800}.note{font-size:10px;line-height:1.5;margin-top:9px}.foot{margin-top:10px;text-align:center;font-size:10px;font-weight:700}@media print{html,body{margin:0!important;padding:0!important}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}} </style></head><body><article class="sheet"><div class="brand"><div><div class="logo">COMPLEMENTO</div><p>San Luis 1365 · Mar del Plata</p></div><div class="tag">${safe(type).toUpperCase()}<div style="font-size:10px;margin-top:5px">NO FISCAL</div></div></div><div class="info"><div><h3>Datos del comprobante</h3><p><b>Fecha:</b> ${safe(date)}</p><p><b>Medio de pago:</b> ${safe(data.payment||'A definir')}</p><p><b>Referencia interna:</b> ${safe(data.id||'Sin número')}</p></div><div><h3>Datos del cliente</h3><p><b>Nombre:</b> ${safe(data.customer||'Consumidor final')}</p><p><b>Dirección:</b> ${safe(data.address||'No informada')}</p><p><b>CUIT / documento:</b> ${safe(data.cuit||'No informado')}</p><p><b>Teléfono:</b> ${safe(data.phone||'No informado')}</p></div></div><section class="detail"><table><thead><tr><th>Descripción</th><th>Cant.</th><th>Precio unit.</th><th>Importe</th></tr></thead><tbody>${data.items.map(x=>`<tr><td>${safe(x.name)}</td><td>${x.qty}</td><td>${money(x.price)}</td><td>${money(x.qty*x.price)}</td></tr>`).join('')}</tbody></table><div class="bottom">${data.notes?'<p><b>Observaciones:</b> '+safe(data.notes)+'</p>':''}<p class="note">Documento comercial interno. NO es factura electrónica ni comprobante fiscal autorizado por ARCA. No incluye CAE ni numeración fiscal.</p></div></section><div class="total"><span>TOTAL</span><span>${money(data.total)}</span></div><div class="foot">COMPLEMENTO · COMPROBANTE NO FISCAL</div></article></body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),500)}
let savingReceipt=false;
async function saveReceipt(){if(!items.length){alert('Agregá productos antes de generar un comprobante.');return null}if(savingReceipt)return null;savingReceipt=true;const x=snapshot();$('posQuote').disabled=true;$('posSale').disabled=true;try{const rows=await api('complemento_pos_sales','POST',{customer:x.customer,address:x.address,cuit:x.cuit,phone:x.phone,payment:x.payment,notes:x.notes,items:x.items,total:x.total});if(!Array.isArray(rows)||!rows.length)throw Error('El servidor no confirmó el guardado');const saved={...rows[0],date:rows[0].created_at};items=[];render();await loadSales();$('posStatus').textContent='✓ Comprobante generado y venta guardada en el panel. Stock sin cambios.';return saved}catch(e){$('posStatus').textContent='No se generó el comprobante porque la venta no se pudo guardar: '+e.message;return null}finally{savingReceipt=false;$('posQuote').disabled=false;$('posSale').disabled=false}}
$('posQuote').onclick=async()=>{if(!items.length)return alert('Agregá productos primero.');const popup=window.open('','_blank');if(popup)popup.document.write('<p style="font-family:Arial">Guardando comprobante…</p>');const d=await saveReceipt();if(d)printQuote(d,'Comprobante de venta',popup);else if(popup)popup.close()};
$('posWhatsApp').onclick=async()=>{const d=await saveReceipt();if(!d)return;const msg=['*COMPLEMENTO · COMPROBANTE NO FISCAL*','Fecha: '+new Date(d.date).toLocaleDateString('es-AR'),'Cliente: '+(d.customer||'Consumidor final'),d.address?'Dirección: '+d.address:'',d.cuit?'CUIT/documento: '+d.cuit:'',d.phone?'Teléfono: '+d.phone:'','*Productos*',...d.items.map(x=>x.qty+' x '+x.name+' — '+money(x.qty*x.price)),'*TOTAL: '+money(d.total)+'*','Documento comercial no fiscal.'].filter(Boolean).join('\n');const digits=(d.phone||'').replace(/\D/g,'');const phone=digits.length>=10?(digits.startsWith('54')?digits:'54'+digits):'';window.location.href='https://wa.me/'+phone+'?text='+encodeURIComponent(msg)};
function history(){$('posHistory').innerHTML=sales.length?sales.slice(0,100).map((x,i)=>`<div class="pos-history-row"><b>${safe(new Date(x.date||x.created_at).toLocaleString('es-AR'))}</b> · ${safe(x.customer||'Consumidor final')} · ${money(x.total)}<div style="font-size:12px;color:#667">${x.items.length} productos · ${safe(x.payment)}</div><button type="button" data-pos-receipt="${i}" style="margin-top:6px">🧾 Ver comprobante</button></div>`).join(''):'<p>No hay ventas registradas todavía.</p>'}
$('posHistory').addEventListener('click',e=>{const b=e.target.closest('[data-pos-receipt]');if(b)printQuote(sales[+b.dataset.posReceipt],'Comprobante de venta')});
async function loadSales(){try{const rows=await api('complemento_pos_sales?select=*&order=created_at.desc&limit=500');sales=rows.map(x=>({...x,date:x.created_at}));history();$('posStatus').textContent='Ventas sincronizadas con el panel.'}catch(e){$('posStatus').textContent='No se pudo cargar el historial: '+e.message}}
$('posSale').onclick=async()=>{if(!items.length)return alert('Agregá productos primero.');if(!confirm('¿Confirmás registrar esta venta? No se descontará stock.'))return;await saveReceipt()};
$('posClear').onclick=()=>{if(items.length&&!confirm('¿Vaciar la venta actual?'))return;items=[];render()};
$('posExport').onclick=()=>{const rows=[['Fecha','ID','Cliente','Teléfono','Pago','Código','Producto','Cantidad','Precio unitario','Subtotal','Total venta','Observaciones']];sales.forEach(s=>s.items.forEach(i=>rows.push([s.date||s.created_at,s.id,s.customer,s.phone,s.payment,i.sku,i.name,i.qty,i.price,i.qty*i.price,s.total,s.notes])));const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='complemento-ventas-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('posClose').onclick=()=>{root.hidden=true};$('posOpen').onclick=async()=>{root.hidden=false;root.scrollIntoView({behavior:'smooth',block:'start'});$('posStatus').textContent='Cargando productos…';try{catalog=await api('complemento_products?select=sku,name,description,price,active&order=name.asc');$('posStatus').textContent=catalog.length+' productos disponibles para buscar.';render();await loadSales();$('posSearch').focus()}catch(e){$('posStatus').textContent='No se pudieron cargar los productos: '+e.message}};render();history();
})();